// Axonometric SVG scene uses real segment-length ratios and editable interface dimensions.
let modelYaw=.43,modelElevation=.43,cutaway=false,orbitPointer=null;
$('viewControls').insertAdjacentHTML('afterbegin','<button data-view="iso" class="active">3D 轴测</button><button id="cutawayBtn" title="切换外观与内部示意">完整外貌</button>');
view='iso';$('viewControls').querySelector('[data-view="side"]').classList.remove('active');
const earlierRenderView=renderView;
const xyz=(x,y,z)=>[x,y,z];
function makeProjector(total){const dimensions=previewDimensionsMm(),H=dimensions.height,D=dimensions.width,cy=Math.cos(modelYaw),sy=Math.sin(modelYaw),ce=Math.cos(modelElevation),se=Math.sin(modelElevation);const raw=([x,y,z])=>[x*cy+z*sy,-y*ce+(x*sy-z*cy)*se];const corners=[];for(const x of [0,total])for(const y of [0,H])for(const z of [0,D])corners.push(raw([x,y,z]));const us=corners.map(p=>p[0]),vs=corners.map(p=>p[1]),minU=Math.min(...us),maxU=Math.max(...us),minV=Math.min(...vs),maxV=Math.max(...vs),scale=Math.min(730/Math.max(1,maxU-minU),185/Math.max(1,maxV-minV));const offsetX=450-(minU+maxU)/2*scale,offsetY=157-(minV+maxV)/2*scale;return p=>{const q=raw(p);return [q[0]*scale+offsetX,q[1]*scale+offsetY]}}
const points=arr=>arr.map(p=>p.map(n=>Number(n.toFixed(1))).join(',')).join(' ');
const polygon=(cls,arr,extra='')=>`<polygon class="${cls}" points="${points(arr)}" ${extra}/>`;
function linkedPartMarkup(s){
  const partId=s.partRef?.partId;if(!partId)return '';
  const part=readEditedPartLibrary().find(item=>item.id===partId);const records=Array.isArray(part?.customScene)?part.customScene:[];
  if(!records.length)return '';
  const dims=part.dimensions||{};const W=Math.max(.001,Number(dims.width||1000)/1000),H=Math.max(.001,Number(dims.height||1000)/1000),D=Math.max(.001,Number(dims.depth||1000)/1000);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  return records.slice(0,80).map((r,i)=>{const g=r.geometry||{},q=g.size||[],sx=Math.max(.001,Number(r.scale?.[0]||1)),sy=Math.max(.001,Number(r.scale?.[1]||1)),x=(Number(r.position?.[0]||0)/W)*28+50,y=86-(Number(r.position?.[1]||0)/H)*55;
    const w=Math.max(3,Math.min(42,(Number(q[0]||.1)*sx/W)*45)),h=Math.max(3,Math.min(62,(Number(q[1]||q[2]||.1)*sy/H)*62)),depth=Math.max(0,Math.min(10,(Number(r.position?.[2]||0)/D)*8));
    const fill=r.material==='black'?'#263238':r.material==='copper'?'#a96035':'#8da0a6',stroke='#31444a',name=esc(r.name||part.name||part.id);
    if(g.type==='sphere')return `<circle class="linked-part" data-linked-name="${name}" cx="${x+depth}" cy="${y}" r="${Math.max(3,w*.5)}" fill="${fill}" stroke="${stroke}"/>`;
    if(g.type==='cylinder'||g.type==='hollowCylinder')return `<g class="linked-part" data-linked-name="${name}"><ellipse cx="${x+depth}" cy="${y-h/2}" rx="${Math.max(2,w*.45)}" ry="${Math.max(1,h*.12)}" fill="${fill}"/><rect x="${x-w/2+depth}" y="${y-h/2}" width="${w}" height="${h}" fill="${fill}" stroke="${stroke}"/><ellipse cx="${x+depth}" cy="${y+h/2}" rx="${Math.max(2,w*.45)}" ry="${Math.max(1,h*.12)}" fill="${fill}" stroke="${stroke}"/></g>`;
    if(g.type==='torus')return `<circle class="linked-part" data-linked-name="${name}" cx="${x+depth}" cy="${y}" r="${Math.max(3,w*.42)}" fill="none" stroke="${fill}" stroke-width="${Math.max(2,w*.16)}"/>`;
    return `<rect class="linked-part" data-linked-name="${name}" x="${x-w/2+depth}" y="${y-h/2}" width="${w}" height="${h}" rx="${g.type==='trapezoid'?3:1}" fill="${fill}" stroke="${stroke}"/>`;
  }).join('')+`<text class="linked-part-label" x="50" y="98" text-anchor="middle">${esc(part.name||part.id)}${part.model?' · '+esc(part.model):''}</text>`;
}
function previewDimensionsMm(){if(formalReadonly){const width=Number(formalInfo.width),height=Number(formalInfo.height),widthKnown=Number.isFinite(width)&&width>0,heightKnown=Number.isFinite(height)&&height>0;return{width:widthKnown?width:2500,height:heightKnown?height:2300,widthKnown,heightKnown}}const c=projects[selectedProject]?.units?.[selectedUnit]?.designConditions||{},width=Number(c.cabinetWidth?.value),height=Number(c.cabinetHeight?.value),widthKnown=Number.isFinite(width)&&width>0,heightKnown=Number.isFinite(height)&&height>0;return{width:widthKnown?width:2500,height:heightKnown?height:2300,widthKnown,heightKnown}}
function modelSymbol(s,x0,x1,z,project){const H=previewDimensionsMm().height,topLeft=project(xyz(x0,H*.9,z)),topRight=project(xyz(x1,H*.9,z)),bottomLeft=project(xyz(x0,H*.1,z));const a=(topRight[0]-topLeft[0])/100,b=(topRight[1]-topLeft[1])/100,c=(bottomLeft[0]-topLeft[0])/100,d=(bottomLeft[1]-topLeft[1])/100;const linked=linkedPartMarkup(s);return `<g class="model-component" transform="matrix(${a} ${b} ${c} ${d} ${topLeft[0]} ${topLeft[1]})">${linked||symbol(s.type)}</g>`}
function modelPort(s,x0,x1,frontZ,project){if(s.isFormalSegment)return {shape:'',anchor:null};ensureGeometry(s);if(s.portSide==='无'||Number(s.portWidth)<=0||Number(s.portHeight)<=0)return {shape:'',anchor:null};const dimensions=previewDimensionsMm(),H=dimensions.height,D=dimensions.width,pw=Math.min(Math.max(10,Number(s.portWidth)),Math.max(10,x1-x0)),ph=Math.min(Math.max(10,Number(s.portHeight)),H),cx=(x0+x1)/2,cy=H/2;let corners;if(['右侧','左侧'].includes(s.portSide)){const z=s.portSide==='右侧'?frontZ:D-frontZ;corners=[xyz(cx-pw/2,cy-ph/2,z),xyz(cx+pw/2,cy-ph/2,z),xyz(cx+pw/2,cy+ph/2,z),xyz(cx-pw/2,cy+ph/2,z)]}else if(['上方','下方'].includes(s.portSide)){const y=s.portSide==='上方'?H:0,depth=Math.min(D,Math.max(80,Number(s.portHeight)));corners=[xyz(cx-pw/2,y,D/2-depth/2),xyz(cx+pw/2,y,D/2-depth/2),xyz(cx+pw/2,y,D/2+depth/2),xyz(cx-pw/2,y,D/2+depth/2)]}else{const x=s.portSide==='左端'?x0:x1,depth=Math.min(D,Math.max(80,Number(s.portWidth)));corners=[xyz(x,cy-ph/2,D/2-depth/2),xyz(x,cy-ph/2,D/2+depth/2),xyz(x,cy+ph/2,D/2+depth/2),xyz(x,cy+ph/2,D/2-depth/2)]}const pp=corners.map(project),anchor=[pp.reduce((n,p)=>n+p[0],0)/4,pp.reduce((n,p)=>n+p[1],0)/4];return {shape:polygon('model-port',pp),anchor}}
function render3D(){const area=$('viewArea'),total=Math.max(1,segments.reduce((n,s)=>n+Math.max(0,Number(s.length)||0),0)),P=makeProjector(total),dimensions=previewDimensionsMm(),H=dimensions.height,D=dimensions.width,frontZ=modelYaw>=0?0:D,backZ=D-frontZ,selected=segments.find(s=>s.id===selectedId);let body='',callout='',cursor=0;
  const base=[P(xyz(0,-140,0)),P(xyz(total,-140,0)),P(xyz(total,0,D)),P(xyz(0,0,D))];body+=polygon('model-base',base);let segmentRanges=[];segments.forEach((s,i)=>{const len=Math.max(1,Number(s.length)||1),x0=cursor,x1=Math.min(total,cursor+len);cursor=x1;segmentRanges.push([s,x0,x1]);const top=[P(xyz(x0,H,0)),P(xyz(x1,H,0)),P(xyz(x1,H,D)),P(xyz(x0,H,D))],side=[P(xyz(x0,0,frontZ)),P(xyz(x1,0,frontZ)),P(xyz(x1,H,frontZ)),P(xyz(x0,H,frontZ))];const chosen=s.id===selectedId;body+=`<g data-segment-id="${escapeHtml(s.id)}">${polygon('model-top',top)}`;if(cutaway)body+=modelSymbol(s,x0,x1,D/2,P);body+=polygon(`${chosen?'model-selected':'model-side'}${cutaway?' cutaway':''}`,side);if(!cutaway)body+=modelSymbol(s,x0,x1,frontZ,P);if(!s.isFormalSegment&&s.doorSide!=='无'){const a=x0+len*.19,b=x0+len*.52,door=[P(xyz(a,300,frontZ)),P(xyz(b,300,frontZ)),P(xyz(b,1850,frontZ)),P(xyz(a,1850,frontZ))];body+=polygon('model-door',door)}const n=P(xyz((x0+x1)/2,H+120,frontZ));body+=`<text class="model-label" x="${n[0]}" y="${n[1]-4}" text-anchor="middle">${String(i+1).padStart(2,'0')}</text></g>`});
  const endX=modelYaw>=0?total:0,end=[P(xyz(endX,0,0)),P(xyz(endX,0,D)),P(xyz(endX,H,D)),P(xyz(endX,H,0))];body+=polygon('model-end',end);
  if(selected){const row=segmentRanges.find(([s])=>s.id===selected.id),[s,x0,x1]=row,port=modelPort(s,x0,x1,frontZ,P);body+=port.shape;const mid=P(xyz((x0+x1)/2,H/2,frontZ)),labelX=675,labelY=40;callout+=`<path class="model-leader" d="M${mid[0]} ${mid[1]} L${labelX-14} ${labelY+35}"/><circle cx="${mid[0]}" cy="${mid[1]}" r="4" fill="#108ea0"/><text class="model-label" x="${labelX}" y="${labelY}">${escapeHtml(s.name)} · 长 ${escapeHtml(s.length)} mm</text>`;if(port.anchor){callout+=`<path class="model-leader" d="M${port.anchor[0]} ${port.anchor[1]} L${labelX-14} ${labelY+62}"/><text class="model-callout" x="${labelX}" y="${labelY+27}">${escapeHtml(s.interfaceName)} · ${escapeHtml(s.portSide)}</text><text class="model-callout" x="${labelX}" y="${labelY+43}">${escapeHtml(s.portWidth)} × ${escapeHtml(s.portHeight)} mm</text>`}else callout+=`<text class="model-callout" x="${labelX}" y="${labelY+27}">${s.isFormalSegment?(Array.isArray(s.connections)&&s.connections.length?`接口记录 ${s.connections.length} 项 · 详见右侧正式数据`:s.connectionsStatus==='none'?'正式数据标记无接口':'正式数据未提供接口'):'当前段无原型接口'}</text>`}
  const start=P(xyz(0,-240,frontZ)),finish=P(xyz(total,-240,frontZ)),arrow=finish[0]>start[0]?'→':'←';area.classList.add('is-3d');area.innerHTML=`<svg viewBox="0 0 900 315" role="img" aria-label="可拖动旋转的机组三维轴测示意"><defs><marker id="modelArrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#1196a8"/></marker></defs><ellipse cx="450" cy="282" rx="355" ry="19" fill="#9db6bd" opacity=".16"/>${body}<path d="M${start[0]} ${start[1]} L${finish[0]} ${finish[1]}" fill="none" stroke="#1594a5" stroke-width="2" marker-end="url(#modelArrow)"/><text class="model-help" x="42" y="296">拖动旋转 · 点击功能段定位 · 气流 ${arrow} · 整机总长 ${total} mm</text>${callout}</svg>`}
renderView=function(){if(formalReadonly&&!['iso','end'].includes(view)){$('viewArea').classList.remove('is-3d');$('viewArea').innerHTML='<div class="result-empty">此方向视图尚未绑定正式方案的接口方位数据。为避免显示原型假设，请在正式只读模式使用三维轴测或端视；段接口的原始记录见右侧。</div>';return}if(view==='iso')render3D();else{ $('viewArea').classList.remove('is-3d');earlierRenderView() }};
window.addEventListener('storage',e=>{if(e.key==='p001-ahu-part-library-v2'||e.key==='p001-ahu-part-library-v1'){restoreSegmentPartRefs();renderInputs();renderOutputs();renderView()}});
