$('viewArea').addEventListener('pointerdown',e=>{if(view!=='svg-iso')return;orbitPointer={x:e.clientX,y:e.clientY,yaw:modelYaw,elevation:modelElevation,id:e.target.closest('[data-segment-id]')?.dataset.segmentId,moved:false};$('viewArea').setPointerCapture(e.pointerId)});
let orbitFrame=0;
$('viewArea').addEventListener('pointermove',e=>{if(!orbitPointer||view!=='svg-iso')return;const dx=e.clientX-orbitPointer.x,dy=e.clientY-orbitPointer.y;if(Math.abs(dx)+Math.abs(dy)<4&&!orbitPointer.moved)return;orbitPointer.moved=true;modelYaw=Math.max(-.95,Math.min(.95,orbitPointer.yaw+dx*.006));modelElevation=Math.max(.2,Math.min(.8,orbitPointer.elevation+dy*.005));if(!orbitFrame)orbitFrame=requestAnimationFrame(()=>{orbitFrame=0;renderView()})});
